insert into questions (id, type, data, status) values ('q_mtf_postherpetic_neuralgia_001', 'MTF', '{"dateAdded":"2026-10-16","rotationIndex":152,"stem":"Postherpetic neuralgia:","choices":["Results from nerve damage caused by the herpes simplex virus","Is more common in older patients","Characteristically includes lancinating pain","Is unresponsive to tricyclic antidepressants","Is prevented by treating the acute phase with aciclovir"],"correct":[false,true,true,false,false],"explanation":"<p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Postherpetic neuralgia is neuropathic pain persisting in the dermatome of a herpes zoster eruption, conventionally at 3 months. It follows reactivation of the varicella zoster virus, and the risk rises steeply with age.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>A. FALSE</strong> &mdash; Herpes zoster is caused by reactivation of latent <em>varicella zoster</em> virus in the dorsal root or trigeminal ganglion, not herpes simplex virus.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>B. TRUE</strong> &mdash; Both herpes zoster and the likelihood of postherpetic neuralgia increase with age; it affects about 15% of patients with acute zoster overall and a considerably higher proportion of the elderly.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>C. TRUE</strong> &mdash; The pain is typically a mixture of continuous burning, intermittent shooting or lancinating pain and allodynia in the affected dermatome. Trophic skin changes may also be present.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>D. FALSE</strong> &mdash; Tricyclic antidepressants, particularly amitriptyline, are an agent of choice. Early treatment is reported to shorten the duration and severity of the pain.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>E. FALSE</strong> &mdash; Antivirals given in the acute phase reduce the severity and duration of the eruption but have not been shown to reliably prevent postherpetic neuralgia. Zoster vaccination reduces the risk.</p><div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Headache</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Epidemiology and Classification</div><table style=\"margin:0\"><tr><th>Prevalence</th><td>Headache is the most common medical complaint &mdash; lifetime prevalence 93% in men and 99% in women</td></tr><tr><th>Primary headache</th><td>Accounts for <strong>&gt;90%</strong> of complaints (migraine, tension-type headache, cluster headache, trigeminal autonomic cephalalgias)</td></tr><tr><th>Pain pathways</th><td>Head and neck pain is mediated via afferent fibres of the trigeminal, nervus intermedius, glossopharyngeal and vagus nerves, plus the upper cervical roots via the occipital nerves</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Primary Headaches at a Glance</div><table style=\"margin:0\"><tr><th>Feature</th><th>Migraine</th><th>Tension-type</th><th>Cluster</th></tr><tr><td><strong>Site</strong></td><td>Unilateral (60%) or bilateral (40%)</td><td>Bilateral, generalised, band-like</td><td><strong>Strictly unilateral</strong></td></tr><tr><td><strong>Character</strong></td><td>Throbbing/pulsating, moderate&ndash;severe</td><td>Pressing/tightening, mild&ndash;moderate</td><td>Extreme intensity</td></tr><tr><td><strong>Duration</strong></td><td>4&ndash;72 hours</td><td>30 minutes &ndash; 7 days</td><td>15&ndash;180 minutes</td></tr><tr><td><strong>Physical activity</strong></td><td>Aggravates</td><td>Unaffected</td><td>Agitation / restlessness</td></tr><tr><td><strong>Associated features</strong></td><td>Nausea, photophobia, phonophobia; aura in 30%</td><td>Nausea/photophobia/phonophobia not prominent</td><td>Ipsilateral autonomic features; Horner&rsquo;s in ~20%</td></tr><tr><td><strong>Pattern</strong></td><td>Recurrent attacks</td><td>Episodic or chronic</td><td>Clusters over weeks&ndash;months, remission for months&ndash;years</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Indications for Neuroimaging</div><table style=\"margin:0\"><tr><th>Indication</th></tr><tr><td>Sudden-onset headache</td></tr><tr><td>History suggestive of focal neurological dysfunction</td></tr><tr><td>Headache with fever / weight loss</td></tr><tr><td>Previous malignancy</td></tr><tr><td>Previous chronic infection (including HIV)</td></tr><tr><td>Neurological abnormality on examination</td></tr><tr><td>Course not matching the presumed diagnosis</td></tr><tr><td>Repeated attendance with the same symptoms</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Migraine</div><table style=\"margin:0\"><tr><th>Epidemiology</th><td>Incidence 8.1/1000; male:female ratio ~1:3; onset commonly in the 2nd&ndash;3rd decade; 70% have a positive family history</td></tr><tr><th>Types</th><td>Migraine without aura (70%) and migraine with aura (30%, &ldquo;classic migraine&rdquo;)</td></tr><tr><th>Aura</th><td>Reversible visual disturbance (homonymous hemianopia, tunnel vision, scotoma, photopsia) &plusmn; photophobia, phonophobia, paraesthesia, hemiplegia, aphasia, nausea, vomiting, abdominal discomfort, diarrhoea</td></tr><tr><th>Headache</th><td>Unilateral (60%) or bilateral (40%), lasting <strong>4&ndash;72 hours</strong>, throbbing/pulsating, moderate&ndash;severe; nausea (90%), vomiting (33%), vertigo, fatigue, confusion, ataxia, drowsiness, photophobia, phonophobia, nasal congestion</td></tr><tr><th>Aggravating factors</th><td>Postural change, activity, raised ICP</td></tr></table><p style=\"margin:14px 0 6px;font-size:13.5px;font-weight:700;color:var(--ink)\">Migraine treatment</p><table style=\"margin:0\"><tr><th>Stress</th><td>Lifestyle change, relaxation therapy, coping strategies, biofeedback, hypnotherapy</td></tr><tr><th>Depression / anxiety</th><td>Specific therapy</td></tr><tr><th>Menstrual migraine</th><td>Mefenamic acid, frovatriptan, transdermal oestrogen, COCP, oestrogen/progesterone implants</td></tr><tr><th>Acute &mdash; stepped management</th><td><strong>1.</strong> Simple oral analgesic + antiemetic (aspirin/ibuprofen/tolfenamic acid + prochlorperazine/domperidone/metoclopramide)<br><strong>2.</strong> Triptan (sumatriptan, zolmitriptan, rizatriptan, naratriptan) + antiemetic, or ergotamine for recurrent relapse<br><strong>3.</strong> CGRP receptor antagonists (gepants)<br>Opioids provide only a small additional benefit</td></tr><tr><th>Prophylaxis</th><td><strong>1st line:</strong> &beta;-blockers, tricyclic antidepressants, ACE inhibitors / angiotensin receptor blockers<br><strong>2nd line:</strong> topiramate, sodium valproate<br><strong>3rd line:</strong> CGRP monoclonal antibodies</td></tr><tr><th>Non-drug</th><td>Botulinum toxin injections, greater occipital nerve blocks, non-invasive neuromodulation therapies</td></tr></table><p style=\"margin:10px 0 0;font-size:12.5px;font-style:italic;color:var(--stone)\">Sodium valproate and topiramate both carry MHRA pregnancy prevention requirements &mdash; avoid in women of childbearing potential unless the conditions of the pregnancy prevention programme are met.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Tension-Type Headache (TTH)</div><table style=\"margin:0\"><tr><th>Point</th></tr><tr><td><strong>Most common primary headache disorder</strong>; lifetime prevalence 69% (men), 88% (women)</td></tr><tr><td>Subdivided into episodic (ETTH &mdash; frequent/infrequent) and chronic (CTTH)</td></tr><tr><td>Generalised pressure/tightness, mild&ndash;moderate, <strong>unaffected by activity</strong>; nausea/photophobia/phonophobia not prominent</td></tr><tr><td>Infrequent ETTH (&lt;1/month): minimal impact, responds to simple analgesics</td></tr><tr><td>Frequent ETTH and CTTH: considerable disability</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Cluster Headache and Trigeminal Autonomic Cephalalgias</div><table style=\"margin:0\"><tr><th>Epidemiology</th><td><strong>Male:female ratio 9:1</strong>; prevalence 0.1&ndash;0.4%; onset typically 20&ndash;40 years</td></tr><tr><th>Pattern</th><td>Attacks occur over <strong>weeks&ndash;months</strong>, then remit for months&ndash;years</td></tr><tr><th>Features</th><td>Extreme pain intensity &rarr; agitation/restlessness; nausea/vomiting uncommon (unlike migraine); ipsilateral Horner&rsquo;s syndrome in ~20%</td></tr><tr><th>Triggers (cluster phase only)</th><td>Alcohol, vasodilators, sleep apnoea-induced hypoxaemia</td></tr><tr><th>Prophylaxis</th><td><strong>Verapamil</strong> (up to 960 mg/day), ergotamine (short-term episodic use), lithium (tolerance can develop), prednisolone (60&ndash;100 mg for 2&ndash;5 days); gabapentin/valproate &mdash; limited evidence</td></tr><tr><th>Acute</th><td>Sumatriptan (intranasal/SC), zolmitriptan, <strong>100% oxygen at &ge;12 L/min</strong> via a non-rebreathe mask for 10&ndash;20 min (effective, particularly in younger patients); intranasal lidocaine in a subgroup; occipital nerve stimulation &mdash; emerging, insufficient evidence</td></tr></table><p style=\"margin:14px 0 6px;font-size:13.5px;font-weight:700;color:var(--ink)\">Other trigeminal autonomic cephalalgias</p><table style=\"margin:0\"><tr><th>Feature</th><th>Paroxysmal hemicrania (PH)</th><th>SUNCT</th></tr><tr><td>Attack duration</td><td>8&ndash;25 minutes</td><td>20&ndash;120 seconds</td></tr><tr><td>Frequency</td><td>5&ndash;24/day</td><td>30&ndash;100/day, mostly daytime</td></tr><tr><td>Sex</td><td>Female predominance (1:3)</td><td>&mdash;</td></tr><tr><td>Key feature</td><td>Resembles cluster headache but fails standard anti-cluster therapy</td><td>Prominent autonomic hyperactivity, especially conjunctival tearing/injection; commonly misdiagnosed as trigeminal neuralgia</td></tr><tr><td>Treatment</td><td><strong>Absolute response to indomethacin</strong> (diagnostic and therapeutic)</td><td>Prevention: topiramate, valproate, gabapentin, lamotrigine (attacks too short to treat acutely)</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Chronic Daily Headache (CDH)</div><table style=\"margin:0\"><tr><th>Point</th></tr><tr><td>Not in ICHD-II R1; prevalence 3&ndash;5%</td></tr><tr><td>Defined as headache on <strong>&gt;15 days/month for &gt;3 months</strong></td></tr><tr><td>Four categories: <strong>transformed migraine</strong> (largest group, 70&ndash;80%), chronic tension-type headache, new daily persistent headache (NDPH), hemicrania continua</td></tr><tr><td>Transformed migraine: periodic migraine &ldquo;transforming&rdquo; to more frequent/continuous headache over years; treated as regular migraine</td></tr><tr><td>Hemicrania continua: rare, unremitting, unilateral; autonomic features (rhinorrhoea, conjunctival injection); responds to indomethacin</td></tr></table><p style=\"margin:14px 0 6px;font-size:13.5px;font-weight:700;color:var(--ink)\">Medication-overuse headache</p><table style=\"margin:0\"><tr><th>Provoking agents</th><td>Ergotamine, triptans, simple analgesics, opioids, combination analgesics</td></tr><tr><th>Prevalence</th><td>Present in up to 40% of chronic migraineurs</td></tr><tr><th>Management</th><td>Education, explanation and follow-up; <strong>abrupt withdrawal</strong> of simple analgesics and triptans, but <strong>gradual tapering</strong> of opioids</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Chronic Facial Pain</div><p style=\"margin:0 0 6px;font-size:13.5px;font-weight:700;color:var(--ink)\">Temporomandibular disorder (TMD)</p><table style=\"margin:0\"><tr><th>Definition</th><td>Generic term for muscle/joint conditions causing symptoms in the TMJ area; prevalence 30&ndash;46% (pain in 5&ndash;15%)</td></tr><tr><th>Investigations</th><td>Joint MRI, bone scintigraphy</td></tr><tr><th>Management</th><td>Self-care programme (jaw relaxation, softer diet, chewing technique, NSAIDs; avoid teeth grinding, prolonged opening, prone sleeping and caffeine), intra-oral splinting, analgesia, physiotherapy, TCAs for chronic pain, CBT techniques</td></tr></table><p style=\"margin:14px 0 6px;font-size:13.5px;font-weight:700;color:var(--ink)\">Trigeminal neuralgia</p><table style=\"margin:0\"><tr><th>Epidemiology</th><td>Incidence 3&ndash;5/100,000; peak onset in the 5th&ndash;6th decade</td></tr><tr><th>Aetiology</th><td>~80% associated with vascular compression; diagnosed in up to 5% of MS patients</td></tr><tr><th>Drug treatment</th><td>First-line <strong>carbamazepine (NNT 1.8)</strong>; others: baclofen, gabapentin, lamotrigine, oxcarbazepine, topiramate; ~70% initially controlled non-surgically</td></tr><tr><th>MVD</th><td>90% short-term relief, 55&ndash;70% long-term; annual recurrence 3.5%; mortality ~0.5%; hearing loss 1%</td></tr></table><p style=\"margin:14px 0 6px;font-size:13.5px;font-weight:700;color:var(--ink)\">Post-herpetic neuralgia (PHN)</p><table style=\"margin:0\"><tr><th>Epidemiology</th><td>Acute zoster incidence 400/100,000/year; PHN occurs in 15% of acute zoster cases</td></tr><tr><th>Definition</th><td>Pain persisting in the affected dermatome at 3 months</td></tr><tr><th>Features</th><td>Typically affects the V1 division; trophic changes (scarring, depigmentation, hair loss), allodynia; most resolve within the first year</td></tr><tr><th>Treatment</th><td><strong>Amitriptyline</strong> is the agent of choice (early treatment shortens duration/severity); gabapentin useful if insomnia; capsaicin cream, topical lidocaine and opioids also used</td></tr></table><p style=\"margin:14px 0 6px;font-size:13.5px;font-weight:700;color:var(--ink)\">Persistent idiopathic facial pain (formerly atypical facial pain)</p><table style=\"margin:0\"><tr><th>Epidemiology</th><td>Incidence 1/100,000; equal sex incidence, but more women seek care</td></tr><tr><th>Associations</th><td>Strong association with functional disorders (IBS) and psychological distress</td></tr><tr><th>Features</th><td>Continuous dull ache with intermittent severe episodes, poorly localised, sparing the joints/muscles of mastication; no sensory loss or physical signs; investigations normal</td></tr><tr><th>Treatment</th><td>Primary analgesics ineffective; poor response to diagnostic nerve block; TCA analgesic response is independent of the antidepressant effect; long-term support often needed</td></tr></table></div></div>\n</div></div>","relevantReading":[{"label":"Headache and chronic facial pain","source":"BJA Education","url":"https://www.bjaed.org/article/S1743-1816(17)30474-2/fulltext"},{"label":"Migraine: symptoms, types, pathophysiology and diagnosis","source":"BJA Education","url":"https://www.bjaed.org/article/S2058-5349(25)00072-1/fulltext"},{"label":"Migraine part 2: evidence-based acute and preventive treatment","source":"BJA Education","url":"https://www.bjaed.org/article/S2058-5349(25)00104-0/fulltext"}]}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_mtf_brief_pain_inventory_001', 'MTF', '{"dateAdded":"2026-10-16","rotationIndex":153,"stem":"The Brief Pain Inventory (BPI):","choices":["Was originally developed to assess cancer pain","Cannot be completed by the patient themselves","Uses word descriptors to assess the quality of pain","Assesses pain over the preceding month","Assesses how much pain interferes with work"],"correct":[true,false,false,false,true],"explanation":"<p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">The Brief Pain Inventory is a short multidimensional questionnaire that scores pain severity and the interference of pain with daily function. It was developed for cancer pain and later validated in chronic non-malignant pain.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>A. TRUE</strong> &mdash; It was developed by Cleeland and colleagues to assess cancer pain, and has since been validated in other chronic pain populations.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>B. FALSE</strong> &mdash; It is designed to be self-completed and takes around 5 minutes; it can also be administered by an interviewer when necessary.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>C. FALSE</strong> &mdash; It does not use word descriptors. Word descriptors of sensory, affective and evaluative pain quality belong to the McGill Pain Questionnaire.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>D. FALSE</strong> &mdash; The standard recall period is the last 24 hours (some versions use the past week), not the past month.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>E. TRUE</strong> &mdash; Seven interference items rate how pain affects general activity, mood, walking ability, normal work, relations with other people, sleep and enjoyment of life.</p><div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Brief Pain Inventory (BPI)</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">The Brief Pain Inventory is a short, patient-completed, multidimensional pain questionnaire. It was developed by Cleeland and colleagues for cancer pain and has since been validated in chronic non-malignant pain and many languages. It measures how severe the pain is and how much it interferes with daily life.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Structure</div><table style=\"margin:0\"><tr><th>Component</th><th>Content</th></tr><tr><td>Pain location</td><td>Shaded body diagram, with the site of worst pain marked</td></tr><tr><td>Pain severity</td><td>Four 0&ndash;10 numerical rating scales: worst, least and average pain in the last 24 hours, and pain right now</td></tr><tr><td>Pain interference</td><td>Seven 0&ndash;10 scales: general activity, mood, walking ability, normal work (including housework), relations with other people, sleep and enjoyment of life</td></tr><tr><td>Treatment and relief</td><td>Current treatments and medications, and the percentage of pain relief obtained (0&ndash;100%)</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Key Features</div><table style=\"margin:0\"><tr><th>Feature</th><th>Detail</th></tr><tr><td>Original population</td><td>Cancer pain; subsequently validated in non-cancer chronic pain</td></tr><tr><td>Administration</td><td>Self-completed in about 5 minutes; can also be interviewer-administered</td></tr><tr><td>Recall period</td><td>Last 24 hours in the standard short form (some versions use the past week)</td></tr><tr><td>Scoring</td><td>Severity score = mean of the four severity items; interference score = mean of the seven interference items</td></tr><tr><td>Forms</td><td>Short form (BPI-SF, 9 items) and long form</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Comparison with the McGill Pain Questionnaire</div><table style=\"margin:0\"><tr><th>Tool</th><th>What it assesses</th></tr><tr><td>Brief Pain Inventory</td><td>Pain location, severity and interference with function; no pain-quality descriptors</td></tr><tr><td>McGill Pain Questionnaire (MPQ)</td><td>Sensory, affective and evaluative quality of pain using word descriptors (Pain Rating Index), plus body diagram and present pain intensity; the short form (SF-MPQ) uses 15 descriptors</td></tr></table><p style=\"margin:10px 0 0;font-size:12.5px;font-style:italic;color:var(--stone)\">Word-descriptor scores belong to the McGill Pain Questionnaire, not the Brief Pain Inventory.</p></div></div>\n</div></div>"}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_mtf_glutamate_001', 'MTF', '{"dateAdded":"2026-10-16","rotationIndex":154,"stem":"Glutamate:","choices":["Is a peptide excitatory neurotransmitter","Reuptake is modulated by glial cells","Acts at AMPA, kainate and NMDA receptors","Acts at G-protein coupled receptors","Is broken down enzymatically within the synaptic cleft"],"correct":[false,true,true,true,false],"explanation":"<p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Glutamate is the main excitatory neurotransmitter of the central nervous system. It acts at both ionotropic and metabotropic receptors and is cleared from the synapse by uptake rather than enzymatic breakdown.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>A. FALSE</strong> &mdash; Glutamate is an excitatory amino acid, not a peptide.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>B. TRUE</strong> &mdash; Excitatory amino acid transporters on astrocytes (EAAT1 and EAAT2) take up most synaptic glutamate, where it is converted to glutamine by glutamine synthetase.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>C. TRUE</strong> &mdash; These are the three families of ionotropic glutamate receptor; AMPA receptors mediate fast transmission and NMDA receptors are central to wind-up and central sensitisation.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>D. TRUE</strong> &mdash; Metabotropic glutamate receptors are G-protein coupled. Group I receptors produce slow, sustained depolarisation, while groups II and III reduce transmitter release.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>E. FALSE</strong> &mdash; There is no enzyme in the cleft that degrades glutamate. Its action is terminated by reuptake into neurones and astrocytes.</p><div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Glutamate</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Glutamate is the principal excitatory neurotransmitter of the central nervous system. It is an amino acid, not a peptide, and it is central to nociceptive transmission in the dorsal horn and to the development of central sensitisation.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Synthesis, Release and Clearance</div><table style=\"margin:0\"><tr><th>Step</th><th>Detail</th></tr><tr><td>Synthesis</td><td>Made in neurones from glutamine (via glutaminase) and from glucose metabolism; packaged into vesicles by vesicular glutamate transporters (VGLUTs)</td></tr><tr><td>Release</td><td>Calcium-dependent exocytosis from the presynaptic terminal</td></tr><tr><td>Clearance</td><td>Not metabolised in the synaptic cleft. Removed by excitatory amino acid transporters (EAATs); EAAT1 and EAAT2 on astrocytes (glial cells) account for most uptake</td></tr><tr><td>Recycling</td><td>Glutamate&ndash;glutamine cycle: astrocytes convert glutamate to glutamine (glutamine synthetase), which returns to the neurone to regenerate glutamate</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Receptors</div><table style=\"margin:0\"><tr><th>Class</th><th>Receptor</th><th>Key features</th></tr><tr><td>Ionotropic</td><td>AMPA</td><td>Fast excitatory transmission; mainly sodium influx (calcium-impermeable if GluA2 is present)</td></tr><tr><td>Ionotropic</td><td>Kainate</td><td>Slower, modulatory excitatory transmission; presynaptic roles</td></tr><tr><td>Ionotropic</td><td>NMDA</td><td>Voltage-dependent magnesium block; requires glycine or D-serine as co-agonist; calcium permeable; slow kinetics</td></tr><tr><td>Metabotropic (G-protein coupled)</td><td>mGluR groups I&ndash;III</td><td>Group I (Gq) produces slow, sustained excitation; groups II and III (Gi/o) reduce transmitter release</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Glutamate in Pain</div><table style=\"margin:0\"><tr><th>Point</th></tr><tr><td>A&delta; and C nociceptive afferents release glutamate (with substance P and CGRP) in laminae I&ndash;II of the dorsal horn</td></tr><tr><td>AMPA receptors mediate the fast postsynaptic response; NMDA receptors are recruited by repetitive C-fibre input, producing wind-up and central sensitisation</td></tr><tr><td>NMDA antagonists: ketamine, dextromethorphan, memantine and magnesium. Gabapentinoids reduce presynaptic release through the &alpha;2&delta; subunit of voltage-gated calcium channels</td></tr><tr><td>Excessive glutamate receptor activation causes excitotoxicity through calcium overload</td></tr></table></div></div>\n</div></div>"}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_sba_opioid_tolerance_001', 'SBA', '{"dateAdded":"2026-10-16","rotationIndex":155,"question":"A 76-year-old man with low back pain has had good pain control with immediate-release morphine for several months. He now says it is not working as well. The most likely explanation is:","choices":["A change of formulation","Addiction","Inappropriate use of a short-acting opioid","Tolerance","Underlying malignancy"],"correct":3,"explanation":"<p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Pain that was well controlled on a stable opioid for months, followed by a reduced effect, is most likely to reflect pharmacological tolerance. Tolerance is an expected adaptation to chronic opioid exposure.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>A. Incorrect.</strong> The patient has been stable on the same preparation for several months, and nothing in the history suggests a change.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>B. Incorrect.</strong> Addiction is a behavioural disorder (compulsive use, loss of control, continued use despite harm). A reduced analgesic effect is not evidence of it.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>C. Incorrect.</strong> Immediate-release morphine has been providing good control for months, so its duration of action is not the new problem.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>D. Correct.</strong> Tolerance is the progressive reduction in effect at a given dose after repeated exposure, through receptor desensitisation and neuroadaptation. It is the most likely explanation in the absence of new features.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>E. Incorrect.</strong> Disease progression should be considered if the pain changes in character or red flags appear, but nothing in the history points to malignancy, and tolerance is the more likely cause.</p><div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Opioid Tolerance and Related Phenomena</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Tolerance is a predictable pharmacological adaptation to repeated opioid exposure: progressively higher doses are needed to produce the same effect. It is an expected physiological response and is not, in itself, evidence of addiction. It must be distinguished from dependence, addiction, hyperalgesia, toxicity and disease progression.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Tolerance: Mechanisms and Features</div><table style=\"margin:0\"><tr><th>Point</th></tr><tr><td>Tolerance is a predictable pharmacological adaptation: progressively higher doses are needed to produce the same effect. The dose&ndash;response curve shifts to the right, developing over days to weeks and faster with higher doses</td></tr><tr><td>Mu-receptor desensitisation: phosphorylation by G-protein receptor kinases, &beta;-arrestin binding and uncoupling from the G-protein; receptor internalisation</td></tr><tr><td>Adaptive changes downstream: adenylyl cyclase upregulation (cAMP superactivation) and NMDA receptor-mediated central sensitisation</td></tr><tr><td>Develops at different rates for different effects: relatively quickly to nausea, sedation and euphoria; little or no tolerance to constipation and miosis</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Tolerance and Related Phenomena</div><table style=\"margin:0\"><tr><th>Term</th><th>Meaning</th></tr><tr><td>Tolerance</td><td>Reduced effect at a given dose after repeated exposure, due to receptor-level neuroadaptation; expected with chronic opioid use and not itself evidence of addiction</td></tr><tr><td>Physical dependence</td><td>Withdrawal syndrome on abrupt cessation, dose reduction or antagonist administration; expected with chronic use and not addiction</td></tr><tr><td>Addiction (opioid use disorder)</td><td>Behavioural disorder: compulsive use, loss of control and continued use despite harm</td></tr><tr><td>Opioid-induced hyperalgesia</td><td>Paradoxical increase in pain sensitivity on opioids; pain may spread beyond the original site and worsens as the dose rises</td></tr><tr><td>Disease progression</td><td>New or changing pain features suggest the underlying condition has changed, rather than tolerance</td></tr><tr><td>Drug diversion</td><td>A third party (for example a carer) redirecting the patient&rsquo;s prescribed opioids for their own use or sale; a carer&rsquo;s behavioural change alongside the patient&rsquo;s rising analgesia requirements should raise this suspicion</td></tr><tr><td>Opioid toxicity</td><td>Accumulation of opioid or active metabolites (e.g. in renal impairment) causing sedation, respiratory depression, pinpoint pupils and myoclonus; unlike withdrawal, it typically causes constipation rather than diarrhoea, with progressive CNS and respiratory depression</td></tr><tr><td>Generalised anxiety disorder</td><td>Persistent, excessive worry about multiple life domains for &ge;6 months with somatic symptoms (restlessness, muscle tension, sleep disturbance); distinct from opioid-related phenomena, though it can coexist with and complicate chronic pain management</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Approach to a Falling Opioid Effect</div><table style=\"margin:0\"><tr><th>Step</th><th>Action</th></tr><tr><td>Reassess</td><td>Look for disease progression, neuropathic component, psychosocial factors, adherence, formulation changes and interacting drugs</td></tr><tr><td>Opioid rotation</td><td>Cross-tolerance between opioids is incomplete: start the new opioid at a reduced fraction (commonly 25&ndash;50%) of the calculated equianalgesic dose</td></tr><tr><td>Limit escalation</td><td>Higher doses rarely add benefit and increase harm; review the benefit&ndash;risk balance at high doses (above 120 mg oral morphine equivalent daily) and consider reduction</td></tr><tr><td>Adjuncts</td><td>Non-opioid and neuropathic agents, NMDA antagonists in selected cases, and non-pharmacological therapies</td></tr></table></div></div>\n</div></div>"}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_sba_trigeminal_neuralgia_investigation_001', 'SBA', '{"dateAdded":"2026-10-16","rotationIndex":156,"question":"A 57-year-old man has had shooting pain in his right cheek for 6 months. It occurs several times a day, is worse in cold weather and wakes him at night. He is pain free between attacks, and examination is normal. The most appropriate investigation is:","choices":["CT scan of the head","MR angiography of the head","Orthopantogram (OPG) X-ray","Skull X-ray including the zygoma","Upper cervical spine X-ray"],"correct":1,"explanation":"<p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">This is trigeminal neuralgia: brief, shooting, unilateral pain in a trigeminal distribution, triggered by cold, with pain-free intervals and no neurological deficit. The diagnosis is clinical, but MRI-based imaging is used to look for neurovascular compression or a secondary cause.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>A. Incorrect.</strong> CT gives poor soft-tissue and posterior fossa resolution and is not the investigation of choice for demonstrating neurovascular compression of the trigeminal root.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>B. Correct.</strong> MR imaging with angiographic sequences shows the trigeminal root and any compressing vessel, and excludes secondary causes such as tumour or demyelination. It is the most appropriate investigation here.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>C. Incorrect.</strong> An OPG assesses the teeth and jaws. It has no role when the history is typical of trigeminal neuralgia and dental pathology has been excluded.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>D. Incorrect.</strong> Plain skull and zygoma films do not image the trigeminal nerve or the posterior fossa and have no diagnostic value.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>E. Incorrect.</strong> Upper cervical spine imaging is not relevant to pain confined to the trigeminal distribution.</p><div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Trigeminal Neuralgia</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Definition</div><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">A unilateral painful disorder characterised by <strong>brief, electric shock-like pains</strong>, abrupt in onset and termination, limited to the distribution of one or more divisions of the trigeminal nerve.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Epidemiology</div><table style=\"margin:0\"><tr><th>Incidence / prevalence</th><td>Annual incidence 3&ndash;5/100,000; worldwide prevalence 10&ndash;300/100,000</td></tr><tr><th>Age</th><td><strong>Peak age of onset 50&ndash;60 years</strong>; rare under 40 years</td></tr><tr><th>Sex</th><td><strong>Male:female ratio 1:2</strong> &mdash; women affected almost twice as often</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Aetiology and Pathophysiology</div><table style=\"margin:0\"><tr><th>Point</th></tr><tr><td>Exact mechanism unclear; the leading model is the <strong>&ldquo;ignition theory&rdquo;</strong> &mdash; abnormal hyperexcitability of afferent neurones in the trigeminal root/ganglion following injury</td></tr><tr><td>Most cases are attributed to <strong>demyelination at the root entry zone</strong>, where Schwann cell (peripheral) myelin meets astrocyte (central) myelin, near the pons</td></tr><tr><td><strong>Ephaptic cross-talk</strong>: demyelinated A&beta; (touch) fibres lying close to A&delta;/C (pain) fibres allow trivial tactile stimulation to trigger pain</td></tr><tr><td><strong>Vascular compression</strong> (typically by the <strong>superior cerebellar artery</strong>) is the most commonly implicated cause of demyelination, supported by surgical/MRI evidence &mdash; although vascular contact is an inconsistent finding and is also seen incidentally in people without TN</td></tr><tr><td><strong>Risk factors</strong>: multiple sclerosis, increasing age, stroke, hypertension (in women), Charcot-Marie-Tooth disease, tumours near the trigeminal root</td></tr><tr><td><strong>MS-associated TN</strong> presents at a <strong>younger age</strong> and tolerates anticonvulsants less well, but responds to interventions similarly to classical TN</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Classification</div><table style=\"margin:0\"><tr><th>Type</th><th>Definition</th><th>Subtypes</th></tr><tr><td><strong>Classical TN</strong></td><td>No apparent cause other than possible neurovascular compression</td><td><strong>Purely paroxysmal</strong> &mdash; pain-free between attacks<br><strong>With concomitant persistent facial pain</strong> (atypical TN / TN type 2) &mdash; low-grade background pain persists; central sensitisation implicated; neurovascular compression often not demonstrable; more treatment-resistant</td></tr><tr><td><strong>Idiopathic TN</strong></td><td>No apparent cause, with no neurovascular compression</td><td><strong>Purely paroxysmal</strong><br><strong>With concomitant persistent facial pain</strong></td></tr><tr><td><strong>Secondary TN</strong></td><td>Caused by an identifiable disorder &mdash; MS, herpes zoster, trauma, space-occupying lesion</td><td>&mdash;</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Diagnostic Criteria (NICE CKS, Adapted from ICHD)</div><table style=\"margin:0\"><tr><th>A</th><td>Paroxysmal attacks lasting a fraction of a second to 2 minutes, in one or more trigeminal divisions, fulfilling B and C</td></tr><tr><th>B</th><td>Pain has at least one of: (1) intense, sharp, superficial or stabbing quality; (2) precipitated from trigger areas or by trigger factors</td></tr><tr><th>C</th><td>Attacks are stereotyped in the individual patient</td></tr><tr><th>D</th><td>No clinically evident neurological deficit</td></tr><tr><th>E</th><td>Not attributed to another disorder</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Red Flags Suggesting Secondary TN</div><table style=\"margin:0\"><tr><th>Red flag</th></tr><tr><td>Sensory deficit, absent trigeminal reflexes, bilateral involvement</td></tr><tr><td>Younger age of onset (&lt;40 years)</td></tr><tr><td>Pain that is persistent rather than paroxysmal</td></tr><tr><td>Difficult-to-control pain</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Differential Diagnosis</div><table style=\"margin:0\"><tr><th>Headache disorders</th><td>Cluster headache, other trigeminal autonomic cephalalgias</td></tr><tr><th>Dental pain</th><td>Cracked tooth, dental abscess</td></tr><tr><th>Joint</th><td>Temporomandibular joint disorder</td></tr><tr><th>Other neuralgias</th><td>Occipital, glossopharyngeal, post-herpetic neuralgia; atypical facial pain</td></tr><tr><th>Tumours</th><td>Acoustic neuroma, meningioma</td></tr><tr><th>Other</th><td>Sinusitis</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Investigations</div><table style=\"margin:0\"><tr><th>Point</th></tr><tr><td>Primarily a <strong>clinical diagnosis</strong> &mdash; no investigation is required to confirm it</td></tr><tr><td><strong>MRI brain</strong> identifies a secondary cause in up to 15% of patients, and high-resolution MRI may identify vascular compression; recommended particularly where red flags are present, and NICE CKS advises specialist referral for MRI assessment in general</td></tr><tr><td>Neurological examination to detect deficit, trigger areas and laterality</td></tr><tr><td>Evoked potentials / quantitative sensory testing / electrophysiology &mdash; insufficient evidence for routine use</td></tr><tr><td>Pre-operative MR tomographic angiography may aid patient selection and outcome prediction for MVD</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Relevant Anatomy</div><table style=\"margin:0\"><tr><th>Point</th></tr><tr><td>CN V is the <strong>largest cranial nerve</strong> &mdash; mixed sensory and motor</td></tr><tr><td>The sensory root forms the <strong>trigeminal (Gasserian) ganglion</strong> within <strong>Meckel&rsquo;s cave</strong> (middle cranial fossa), dividing into V1 (ophthalmic), V2 (maxillary) and V3 (mandibular)</td></tr><tr><td>Exits: <strong>V1</strong> via the superior orbital fissure; <strong>V2</strong> via the foramen rotundum; <strong>V3</strong> via the foramen ovale</td></tr><tr><td>The motor root travels with the sensory root but distributes <strong>only via V3</strong>, supplying the muscles of mastication</td></tr><tr><td>Parasympathetic fibres are carried via trigeminal branches to the lacrimal gland (V1/V2), nasal glands (V2) and submandibular/sublingual/parotid glands (V3)</td></tr></table><div style=\"text-align:center;margin-top:12px\"><img src=\"images/trigeminal-nerve-divisions.svg\" alt=\"The trigeminal nerve: sensory root from the pons to the Gasserian ganglion in Meckel&rsquo;s cave, dividing into V1 (superior orbital fissure), V2 (foramen rotundum) and V3 (foramen ovale), with the motor root joining V3, and the three levels targeted by surgery\" style=\"max-width:100%;border-radius:10px;margin-top:4px;border:1px solid #EDE3D7\"></div></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Pharmacological Management</div><table style=\"margin:0\"><tr><th>Drug</th><th>Role</th><th>Notes</th></tr><tr><td><strong>Carbamazepine</strong></td><td><strong>First-line</strong></td><td><strong>NNT 1.8</strong>; blocks use-dependent sodium channels and may prevent synaptic transmission in the trigeminal nucleus. Start 100 mg once or twice daily and titrate; usual dose 200 mg 3&ndash;4 times daily, max 1.6 g/day. Side effects: drowsiness, dizziness, rash, liver damage, hyponatraemia, ataxia &mdash; monitor LFTs, FBC and electrolytes</td></tr><tr><td><strong>Oxcarbazepine</strong></td><td>Alternative</td><td>Carbamazepine derivative; better side-effect profile, similar efficacy</td></tr><tr><td>Gabapentin, pregabalin, amitriptyline</td><td>Commonly used</td><td>Efficacy specific to TN not strongly evidenced (the NICE neuropathic pain pathway explicitly excludes TN)</td></tr><tr><td>Baclofen, lamotrigine</td><td>Add-on therapy</td><td>Baclofen may help in MS-associated TN</td></tr><tr><td>Phenytoin</td><td>Limited benefit</td><td>Used in some cases</td></tr><tr><td>Opioids</td><td>Not recommended</td><td>Ineffective for paroxysmal TN pain; NICE advises against starting them in non-specialist settings</td></tr></table><p style=\"margin:10px 0 0;font-size:12.5px;font-style:italic;color:var(--stone)\">If carbamazepine is ineffective, not tolerated or contraindicated &rarr; seek specialist advice / early referral, rather than cycling through other non-specific analgesics.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Surgical Management (Failed or Intolerant of Pharmacotherapy)</div><table style=\"margin:0\"><tr><th>Level</th><th>Procedure</th><th>Outcome</th><th>Risks</th></tr><tr><td><strong>Peripheral</strong></td><td>Branch neurolysis &mdash; laser, alcohol, neurectomy</td><td>Short-term relief (6 months&ndash;1 year); useful if unfit for other surgery, or as an emergency procedure</td><td>Dysaesthesia</td></tr><tr><td><strong>Gasserian ganglion</strong> (percutaneous, via foramen ovale under fluoroscopy)</td><td>Thermal (radiofrequency), chemical (glycerol/phenol/alcohol) or mechanical (balloon compression) ablation</td><td>Relief for ~4&ndash;5 years in 50% of patients</td><td>High incidence of sensory loss/dysaesthesia; ~4% develop <strong>anaesthesia dolorosa</strong>. Balloon compression specifically: arrhythmias, aseptic meningitis, temporary diplopia</td></tr><tr><td><strong>Posterior fossa</strong></td><td><strong>Microvascular decompression (MVD)</strong> &mdash; suboccipital craniotomy; the vessel (typically the superior cerebellar artery) is separated from the nerve root with Teflon felt</td><td><strong>Best initial success rate (80&ndash;90%)</strong> and the most sustained relief of all procedures; 10-year relapse ~30&ndash;40%</td><td>Mortality ~0.5% (major neurosurgery); aseptic meningitis (11%), hearing loss (1%), sensory loss (7%), CSF leak, haematoma, infarcts</td></tr><tr><td><strong>Posterior fossa</strong></td><td><strong>Gamma knife stereotactic radiosurgery</strong> &mdash; focused radiation to the nerve root where vascular compression is confirmed on MRI mapping</td><td>Complete relief in up to 69% by 1 year, but benefit may not be sustained; can be repeated; an option for patients unsuitable for MVD</td><td>Facial numbness, paraesthesia</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Psychological and Other Interventions</div><table style=\"margin:0\"><tr><th>Point</th></tr><tr><td><strong>Multidisciplinary input</strong>, including psychology, is valuable given the significant impact on wellbeing; CBT and ACT are considered, although the evidence quality is limited</td></tr><tr><td>Neuromodulation (trigeminal, occipital, peripheral nerve, spinal cord, motor cortex stimulation) &mdash; not yet robust enough for routine use</td></tr><tr><td>Non-invasive repetitive transcranial magnetic stimulation &mdash; benefit shown in orofacial pain generally; role in TN specifically not established</td></tr><tr><td>Botulinum toxin type A &mdash; case reports/open studies only; larger trials needed</td></tr><tr><td>TENS, acupuncture, 5% lidocaine patches &mdash; tried with varying results</td></tr></table></div></div>\n</div></div>","relevantReading":[{"label":"Trigeminal neuralgia","source":"BJA Education","url":"https://www.bjaed.org/article/S2058-5349(17)30037-9/fulltext"},{"label":"Diagnosis and management of chronic facial pain","source":"BJA Education","url":"https://www.bjaed.org/article/S2058-5349(20)30002-0/fulltext"},{"label":"Trigeminal neuralgia","source":"NICE CKS","url":"https://cks.nice.org.uk/topics/trigeminal-neuralgia/"}]}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_sba_cluster_headache_alcohol_trigger_001', 'SBA', '{"dateAdded":"2026-10-16","rotationIndex":157,"question":"A 28-year-old man attends the pain clinic with severe headaches over the last six months. They are triggered by drinking lager with friends. He had similar headaches a few years ago, which resolved. The most likely diagnosis is:","choices":["Cerebral metastasis","Chronic daily headache","Cluster headache","Migraine","Tension-type headache"],"correct":2,"explanation":"<p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">Attacks clustered over weeks to months, remitting for months or years, in a young man with alcohol as a trigger, point to cluster headache. Alcohol triggers attacks during a cluster period only.</p><p style=\"margin:12px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>A. Incorrect.</strong> Metastasis would be unusual at this age without a known primary, and does not explain a previous episode that fully resolved.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>B. Incorrect.</strong> Chronic daily headache requires headache on more than 15 days per month for more than 3 months; the history describes alcohol-triggered attacks with earlier remission.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>C. Correct.</strong> Cluster headache has a male predominance, onset between 20 and 40 years, attacks over weeks to months followed by remission, and alcohol as a recognised trigger during the cluster phase.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>D. Incorrect.</strong> Migraine is commoner in women, and alcohol is a recognised but less specific trigger; the remitting cluster pattern in a young man favours cluster headache.</p><p style=\"margin:8px 0 0;font-size:14px;line-height:1.65;color:var(--ink-soft)\"><strong>E. Incorrect.</strong> Tension-type headache is generalised, pressing and mild to moderate, and is not typically triggered by alcohol or described as severe.</p><div style=\"margin-top:18px\"><div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Headache</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Epidemiology and Classification</div><table style=\"margin:0\"><tr><th>Prevalence</th><td>Headache is the most common medical complaint &mdash; lifetime prevalence 93% in men and 99% in women</td></tr><tr><th>Primary headache</th><td>Accounts for <strong>&gt;90%</strong> of complaints (migraine, tension-type headache, cluster headache, trigeminal autonomic cephalalgias)</td></tr><tr><th>Pain pathways</th><td>Head and neck pain is mediated via afferent fibres of the trigeminal, nervus intermedius, glossopharyngeal and vagus nerves, plus the upper cervical roots via the occipital nerves</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Primary Headaches at a Glance</div><table style=\"margin:0\"><tr><th>Feature</th><th>Migraine</th><th>Tension-type</th><th>Cluster</th></tr><tr><td><strong>Site</strong></td><td>Unilateral (60%) or bilateral (40%)</td><td>Bilateral, generalised, band-like</td><td><strong>Strictly unilateral</strong></td></tr><tr><td><strong>Character</strong></td><td>Throbbing/pulsating, moderate&ndash;severe</td><td>Pressing/tightening, mild&ndash;moderate</td><td>Extreme intensity</td></tr><tr><td><strong>Duration</strong></td><td>4&ndash;72 hours</td><td>30 minutes &ndash; 7 days</td><td>15&ndash;180 minutes</td></tr><tr><td><strong>Physical activity</strong></td><td>Aggravates</td><td>Unaffected</td><td>Agitation / restlessness</td></tr><tr><td><strong>Associated features</strong></td><td>Nausea, photophobia, phonophobia; aura in 30%</td><td>Nausea/photophobia/phonophobia not prominent</td><td>Ipsilateral autonomic features; Horner&rsquo;s in ~20%</td></tr><tr><td><strong>Pattern</strong></td><td>Recurrent attacks</td><td>Episodic or chronic</td><td>Clusters over weeks&ndash;months, remission for months&ndash;years</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Indications for Neuroimaging</div><table style=\"margin:0\"><tr><th>Indication</th></tr><tr><td>Sudden-onset headache</td></tr><tr><td>History suggestive of focal neurological dysfunction</td></tr><tr><td>Headache with fever / weight loss</td></tr><tr><td>Previous malignancy</td></tr><tr><td>Previous chronic infection (including HIV)</td></tr><tr><td>Neurological abnormality on examination</td></tr><tr><td>Course not matching the presumed diagnosis</td></tr><tr><td>Repeated attendance with the same symptoms</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Migraine</div><table style=\"margin:0\"><tr><th>Epidemiology</th><td>Incidence 8.1/1000; male:female ratio ~1:3; onset commonly in the 2nd&ndash;3rd decade; 70% have a positive family history</td></tr><tr><th>Types</th><td>Migraine without aura (70%) and migraine with aura (30%, &ldquo;classic migraine&rdquo;)</td></tr><tr><th>Aura</th><td>Reversible visual disturbance (homonymous hemianopia, tunnel vision, scotoma, photopsia) &plusmn; photophobia, phonophobia, paraesthesia, hemiplegia, aphasia, nausea, vomiting, abdominal discomfort, diarrhoea</td></tr><tr><th>Headache</th><td>Unilateral (60%) or bilateral (40%), lasting <strong>4&ndash;72 hours</strong>, throbbing/pulsating, moderate&ndash;severe; nausea (90%), vomiting (33%), vertigo, fatigue, confusion, ataxia, drowsiness, photophobia, phonophobia, nasal congestion</td></tr><tr><th>Aggravating factors</th><td>Postural change, activity, raised ICP</td></tr></table><p style=\"margin:14px 0 6px;font-size:13.5px;font-weight:700;color:var(--ink)\">Migraine treatment</p><table style=\"margin:0\"><tr><th>Stress</th><td>Lifestyle change, relaxation therapy, coping strategies, biofeedback, hypnotherapy</td></tr><tr><th>Depression / anxiety</th><td>Specific therapy</td></tr><tr><th>Menstrual migraine</th><td>Mefenamic acid, frovatriptan, transdermal oestrogen, COCP, oestrogen/progesterone implants</td></tr><tr><th>Acute &mdash; stepped management</th><td><strong>1.</strong> Simple oral analgesic + antiemetic (aspirin/ibuprofen/tolfenamic acid + prochlorperazine/domperidone/metoclopramide)<br><strong>2.</strong> Triptan (sumatriptan, zolmitriptan, rizatriptan, naratriptan) + antiemetic, or ergotamine for recurrent relapse<br><strong>3.</strong> CGRP receptor antagonists (gepants)<br>Opioids provide only a small additional benefit</td></tr><tr><th>Prophylaxis</th><td><strong>1st line:</strong> &beta;-blockers, tricyclic antidepressants, ACE inhibitors / angiotensin receptor blockers<br><strong>2nd line:</strong> topiramate, sodium valproate<br><strong>3rd line:</strong> CGRP monoclonal antibodies</td></tr><tr><th>Non-drug</th><td>Botulinum toxin injections, greater occipital nerve blocks, non-invasive neuromodulation therapies</td></tr></table><p style=\"margin:10px 0 0;font-size:12.5px;font-style:italic;color:var(--stone)\">Sodium valproate and topiramate both carry MHRA pregnancy prevention requirements &mdash; avoid in women of childbearing potential unless the conditions of the pregnancy prevention programme are met.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Tension-Type Headache (TTH)</div><table style=\"margin:0\"><tr><th>Point</th></tr><tr><td><strong>Most common primary headache disorder</strong>; lifetime prevalence 69% (men), 88% (women)</td></tr><tr><td>Subdivided into episodic (ETTH &mdash; frequent/infrequent) and chronic (CTTH)</td></tr><tr><td>Generalised pressure/tightness, mild&ndash;moderate, <strong>unaffected by activity</strong>; nausea/photophobia/phonophobia not prominent</td></tr><tr><td>Infrequent ETTH (&lt;1/month): minimal impact, responds to simple analgesics</td></tr><tr><td>Frequent ETTH and CTTH: considerable disability</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Cluster Headache and Trigeminal Autonomic Cephalalgias</div><table style=\"margin:0\"><tr><th>Epidemiology</th><td><strong>Male:female ratio 9:1</strong>; prevalence 0.1&ndash;0.4%; onset typically 20&ndash;40 years</td></tr><tr><th>Pattern</th><td>Attacks occur over <strong>weeks&ndash;months</strong>, then remit for months&ndash;years</td></tr><tr><th>Features</th><td>Extreme pain intensity &rarr; agitation/restlessness; nausea/vomiting uncommon (unlike migraine); ipsilateral Horner&rsquo;s syndrome in ~20%</td></tr><tr><th>Triggers (cluster phase only)</th><td>Alcohol, vasodilators, sleep apnoea-induced hypoxaemia</td></tr><tr><th>Prophylaxis</th><td><strong>Verapamil</strong> (up to 960 mg/day), ergotamine (short-term episodic use), lithium (tolerance can develop), prednisolone (60&ndash;100 mg for 2&ndash;5 days); gabapentin/valproate &mdash; limited evidence</td></tr><tr><th>Acute</th><td>Sumatriptan (intranasal/SC), zolmitriptan, <strong>100% oxygen at &ge;12 L/min</strong> via a non-rebreathe mask for 10&ndash;20 min (effective, particularly in younger patients); intranasal lidocaine in a subgroup; occipital nerve stimulation &mdash; emerging, insufficient evidence</td></tr></table><p style=\"margin:14px 0 6px;font-size:13.5px;font-weight:700;color:var(--ink)\">Other trigeminal autonomic cephalalgias</p><table style=\"margin:0\"><tr><th>Feature</th><th>Paroxysmal hemicrania (PH)</th><th>SUNCT</th></tr><tr><td>Attack duration</td><td>8&ndash;25 minutes</td><td>20&ndash;120 seconds</td></tr><tr><td>Frequency</td><td>5&ndash;24/day</td><td>30&ndash;100/day, mostly daytime</td></tr><tr><td>Sex</td><td>Female predominance (1:3)</td><td>&mdash;</td></tr><tr><td>Key feature</td><td>Resembles cluster headache but fails standard anti-cluster therapy</td><td>Prominent autonomic hyperactivity, especially conjunctival tearing/injection; commonly misdiagnosed as trigeminal neuralgia</td></tr><tr><td>Treatment</td><td><strong>Absolute response to indomethacin</strong> (diagnostic and therapeutic)</td><td>Prevention: topiramate, valproate, gabapentin, lamotrigine (attacks too short to treat acutely)</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Chronic Daily Headache (CDH)</div><table style=\"margin:0\"><tr><th>Point</th></tr><tr><td>Not in ICHD-II R1; prevalence 3&ndash;5%</td></tr><tr><td>Defined as headache on <strong>&gt;15 days/month for &gt;3 months</strong></td></tr><tr><td>Four categories: <strong>transformed migraine</strong> (largest group, 70&ndash;80%), chronic tension-type headache, new daily persistent headache (NDPH), hemicrania continua</td></tr><tr><td>Transformed migraine: periodic migraine &ldquo;transforming&rdquo; to more frequent/continuous headache over years; treated as regular migraine</td></tr><tr><td>Hemicrania continua: rare, unremitting, unilateral; autonomic features (rhinorrhoea, conjunctival injection); responds to indomethacin</td></tr></table><p style=\"margin:14px 0 6px;font-size:13.5px;font-weight:700;color:var(--ink)\">Medication-overuse headache</p><table style=\"margin:0\"><tr><th>Provoking agents</th><td>Ergotamine, triptans, simple analgesics, opioids, combination analgesics</td></tr><tr><th>Prevalence</th><td>Present in up to 40% of chronic migraineurs</td></tr><tr><th>Management</th><td>Education, explanation and follow-up; <strong>abrupt withdrawal</strong> of simple analgesics and triptans, but <strong>gradual tapering</strong> of opioids</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Chronic Facial Pain</div><p style=\"margin:0 0 6px;font-size:13.5px;font-weight:700;color:var(--ink)\">Temporomandibular disorder (TMD)</p><table style=\"margin:0\"><tr><th>Definition</th><td>Generic term for muscle/joint conditions causing symptoms in the TMJ area; prevalence 30&ndash;46% (pain in 5&ndash;15%)</td></tr><tr><th>Investigations</th><td>Joint MRI, bone scintigraphy</td></tr><tr><th>Management</th><td>Self-care programme (jaw relaxation, softer diet, chewing technique, NSAIDs; avoid teeth grinding, prolonged opening, prone sleeping and caffeine), intra-oral splinting, analgesia, physiotherapy, TCAs for chronic pain, CBT techniques</td></tr></table><p style=\"margin:14px 0 6px;font-size:13.5px;font-weight:700;color:var(--ink)\">Trigeminal neuralgia</p><table style=\"margin:0\"><tr><th>Epidemiology</th><td>Incidence 3&ndash;5/100,000; peak onset in the 5th&ndash;6th decade</td></tr><tr><th>Aetiology</th><td>~80% associated with vascular compression; diagnosed in up to 5% of MS patients</td></tr><tr><th>Drug treatment</th><td>First-line <strong>carbamazepine (NNT 1.8)</strong>; others: baclofen, gabapentin, lamotrigine, oxcarbazepine, topiramate; ~70% initially controlled non-surgically</td></tr><tr><th>MVD</th><td>90% short-term relief, 55&ndash;70% long-term; annual recurrence 3.5%; mortality ~0.5%; hearing loss 1%</td></tr></table><p style=\"margin:14px 0 6px;font-size:13.5px;font-weight:700;color:var(--ink)\">Post-herpetic neuralgia (PHN)</p><table style=\"margin:0\"><tr><th>Epidemiology</th><td>Acute zoster incidence 400/100,000/year; PHN occurs in 15% of acute zoster cases</td></tr><tr><th>Definition</th><td>Pain persisting in the affected dermatome at 3 months</td></tr><tr><th>Features</th><td>Typically affects the V1 division; trophic changes (scarring, depigmentation, hair loss), allodynia; most resolve within the first year</td></tr><tr><th>Treatment</th><td><strong>Amitriptyline</strong> is the agent of choice (early treatment shortens duration/severity); gabapentin useful if insomnia; capsaicin cream, topical lidocaine and opioids also used</td></tr></table><p style=\"margin:14px 0 6px;font-size:13.5px;font-weight:700;color:var(--ink)\">Persistent idiopathic facial pain (formerly atypical facial pain)</p><table style=\"margin:0\"><tr><th>Epidemiology</th><td>Incidence 1/100,000; equal sex incidence, but more women seek care</td></tr><tr><th>Associations</th><td>Strong association with functional disorders (IBS) and psychological distress</td></tr><tr><th>Features</th><td>Continuous dull ache with intermittent severe episodes, poorly localised, sparing the joints/muscles of mastication; no sensory loss or physical signs; investigations normal</td></tr><tr><th>Treatment</th><td>Primary analgesics ineffective; poor response to diagnostic nerve block; TCA analgesic response is independent of the antidepressant effect; long-term support often needed</td></tr></table></div></div>\n</div></div>","relevantReading":[{"label":"Headache and chronic facial pain","source":"BJA Education","url":"https://www.bjaed.org/article/S1743-1816(17)30474-2/fulltext"},{"label":"Migraine: symptoms, types, pathophysiology and diagnosis","source":"BJA Education","url":"https://www.bjaed.org/article/S2058-5349(25)00072-1/fulltext"},{"label":"Migraine part 2: evidence-based acute and preventive treatment","source":"BJA Education","url":"https://www.bjaed.org/article/S2058-5349(25)00104-0/fulltext"}]}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_emq_facial_pain_diagnosis_001', 'EMQ', '{"dateAdded":"2026-10-16","rotationIndex":158,"stem":"Facial pain","lead":"For each scenario below, choose the single most likely diagnosis from the list above. Each option may be used once, more than once, or not at all.","options":["Dental pain","Migraine","Postherpetic neuralgia","Sinus pain","Temporomandibular joint pain","Trauma","Trigeminal neuralgia","Tumour-related pain"],"questions":[{"question":"A 65-year-old woman is referred by the maxillofacial surgeons because no cause for her pain has been found inside or outside the mouth. She has had right cheek pain for a year, described as a constant ache with shooting sensations. She has no history of a rash. There are no sensory changes, but there is widespread tenderness on both sides of the face.","correct":3,"explanation":"<strong>D. Sinus pain.</strong> A constant deep ache over the cheeks with bilateral facial tenderness and no oral cause, no sensory loss and no rash fits sinus pain. Dental pain has been excluded, postherpetic neuralgia needs a previous zoster rash, and trigeminal neuralgia is paroxysmal rather than constant."},{"question":"A 38-year-old woman is referred with brief spasms of facial pain. She recently had an episode of blurred vision and ataxia and is awaiting neurology review.","correct":6,"explanation":"<strong>G. Trigeminal neuralgia.</strong> Brief paroxysmal facial pain at this age, with a recent episode of visual disturbance and ataxia, suggests trigeminal neuralgia secondary to multiple sclerosis. Onset below 40 years should raise suspicion of a secondary cause."}],"reference":"<div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Headache</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Epidemiology and Classification</div><table style=\"margin:0\"><tr><th>Prevalence</th><td>Headache is the most common medical complaint &mdash; lifetime prevalence 93% in men and 99% in women</td></tr><tr><th>Primary headache</th><td>Accounts for <strong>&gt;90%</strong> of complaints (migraine, tension-type headache, cluster headache, trigeminal autonomic cephalalgias)</td></tr><tr><th>Pain pathways</th><td>Head and neck pain is mediated via afferent fibres of the trigeminal, nervus intermedius, glossopharyngeal and vagus nerves, plus the upper cervical roots via the occipital nerves</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Primary Headaches at a Glance</div><table style=\"margin:0\"><tr><th>Feature</th><th>Migraine</th><th>Tension-type</th><th>Cluster</th></tr><tr><td><strong>Site</strong></td><td>Unilateral (60%) or bilateral (40%)</td><td>Bilateral, generalised, band-like</td><td><strong>Strictly unilateral</strong></td></tr><tr><td><strong>Character</strong></td><td>Throbbing/pulsating, moderate&ndash;severe</td><td>Pressing/tightening, mild&ndash;moderate</td><td>Extreme intensity</td></tr><tr><td><strong>Duration</strong></td><td>4&ndash;72 hours</td><td>30 minutes &ndash; 7 days</td><td>15&ndash;180 minutes</td></tr><tr><td><strong>Physical activity</strong></td><td>Aggravates</td><td>Unaffected</td><td>Agitation / restlessness</td></tr><tr><td><strong>Associated features</strong></td><td>Nausea, photophobia, phonophobia; aura in 30%</td><td>Nausea/photophobia/phonophobia not prominent</td><td>Ipsilateral autonomic features; Horner&rsquo;s in ~20%</td></tr><tr><td><strong>Pattern</strong></td><td>Recurrent attacks</td><td>Episodic or chronic</td><td>Clusters over weeks&ndash;months, remission for months&ndash;years</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Indications for Neuroimaging</div><table style=\"margin:0\"><tr><th>Indication</th></tr><tr><td>Sudden-onset headache</td></tr><tr><td>History suggestive of focal neurological dysfunction</td></tr><tr><td>Headache with fever / weight loss</td></tr><tr><td>Previous malignancy</td></tr><tr><td>Previous chronic infection (including HIV)</td></tr><tr><td>Neurological abnormality on examination</td></tr><tr><td>Course not matching the presumed diagnosis</td></tr><tr><td>Repeated attendance with the same symptoms</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Migraine</div><table style=\"margin:0\"><tr><th>Epidemiology</th><td>Incidence 8.1/1000; male:female ratio ~1:3; onset commonly in the 2nd&ndash;3rd decade; 70% have a positive family history</td></tr><tr><th>Types</th><td>Migraine without aura (70%) and migraine with aura (30%, &ldquo;classic migraine&rdquo;)</td></tr><tr><th>Aura</th><td>Reversible visual disturbance (homonymous hemianopia, tunnel vision, scotoma, photopsia) &plusmn; photophobia, phonophobia, paraesthesia, hemiplegia, aphasia, nausea, vomiting, abdominal discomfort, diarrhoea</td></tr><tr><th>Headache</th><td>Unilateral (60%) or bilateral (40%), lasting <strong>4&ndash;72 hours</strong>, throbbing/pulsating, moderate&ndash;severe; nausea (90%), vomiting (33%), vertigo, fatigue, confusion, ataxia, drowsiness, photophobia, phonophobia, nasal congestion</td></tr><tr><th>Aggravating factors</th><td>Postural change, activity, raised ICP</td></tr></table><p style=\"margin:14px 0 6px;font-size:13.5px;font-weight:700;color:var(--ink)\">Migraine treatment</p><table style=\"margin:0\"><tr><th>Stress</th><td>Lifestyle change, relaxation therapy, coping strategies, biofeedback, hypnotherapy</td></tr><tr><th>Depression / anxiety</th><td>Specific therapy</td></tr><tr><th>Menstrual migraine</th><td>Mefenamic acid, frovatriptan, transdermal oestrogen, COCP, oestrogen/progesterone implants</td></tr><tr><th>Acute &mdash; stepped management</th><td><strong>1.</strong> Simple oral analgesic + antiemetic (aspirin/ibuprofen/tolfenamic acid + prochlorperazine/domperidone/metoclopramide)<br><strong>2.</strong> Triptan (sumatriptan, zolmitriptan, rizatriptan, naratriptan) + antiemetic, or ergotamine for recurrent relapse<br><strong>3.</strong> CGRP receptor antagonists (gepants)<br>Opioids provide only a small additional benefit</td></tr><tr><th>Prophylaxis</th><td><strong>1st line:</strong> &beta;-blockers, tricyclic antidepressants, ACE inhibitors / angiotensin receptor blockers<br><strong>2nd line:</strong> topiramate, sodium valproate<br><strong>3rd line:</strong> CGRP monoclonal antibodies</td></tr><tr><th>Non-drug</th><td>Botulinum toxin injections, greater occipital nerve blocks, non-invasive neuromodulation therapies</td></tr></table><p style=\"margin:10px 0 0;font-size:12.5px;font-style:italic;color:var(--stone)\">Sodium valproate and topiramate both carry MHRA pregnancy prevention requirements &mdash; avoid in women of childbearing potential unless the conditions of the pregnancy prevention programme are met.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Tension-Type Headache (TTH)</div><table style=\"margin:0\"><tr><th>Point</th></tr><tr><td><strong>Most common primary headache disorder</strong>; lifetime prevalence 69% (men), 88% (women)</td></tr><tr><td>Subdivided into episodic (ETTH &mdash; frequent/infrequent) and chronic (CTTH)</td></tr><tr><td>Generalised pressure/tightness, mild&ndash;moderate, <strong>unaffected by activity</strong>; nausea/photophobia/phonophobia not prominent</td></tr><tr><td>Infrequent ETTH (&lt;1/month): minimal impact, responds to simple analgesics</td></tr><tr><td>Frequent ETTH and CTTH: considerable disability</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Cluster Headache and Trigeminal Autonomic Cephalalgias</div><table style=\"margin:0\"><tr><th>Epidemiology</th><td><strong>Male:female ratio 9:1</strong>; prevalence 0.1&ndash;0.4%; onset typically 20&ndash;40 years</td></tr><tr><th>Pattern</th><td>Attacks occur over <strong>weeks&ndash;months</strong>, then remit for months&ndash;years</td></tr><tr><th>Features</th><td>Extreme pain intensity &rarr; agitation/restlessness; nausea/vomiting uncommon (unlike migraine); ipsilateral Horner&rsquo;s syndrome in ~20%</td></tr><tr><th>Triggers (cluster phase only)</th><td>Alcohol, vasodilators, sleep apnoea-induced hypoxaemia</td></tr><tr><th>Prophylaxis</th><td><strong>Verapamil</strong> (up to 960 mg/day), ergotamine (short-term episodic use), lithium (tolerance can develop), prednisolone (60&ndash;100 mg for 2&ndash;5 days); gabapentin/valproate &mdash; limited evidence</td></tr><tr><th>Acute</th><td>Sumatriptan (intranasal/SC), zolmitriptan, <strong>100% oxygen at &ge;12 L/min</strong> via a non-rebreathe mask for 10&ndash;20 min (effective, particularly in younger patients); intranasal lidocaine in a subgroup; occipital nerve stimulation &mdash; emerging, insufficient evidence</td></tr></table><p style=\"margin:14px 0 6px;font-size:13.5px;font-weight:700;color:var(--ink)\">Other trigeminal autonomic cephalalgias</p><table style=\"margin:0\"><tr><th>Feature</th><th>Paroxysmal hemicrania (PH)</th><th>SUNCT</th></tr><tr><td>Attack duration</td><td>8&ndash;25 minutes</td><td>20&ndash;120 seconds</td></tr><tr><td>Frequency</td><td>5&ndash;24/day</td><td>30&ndash;100/day, mostly daytime</td></tr><tr><td>Sex</td><td>Female predominance (1:3)</td><td>&mdash;</td></tr><tr><td>Key feature</td><td>Resembles cluster headache but fails standard anti-cluster therapy</td><td>Prominent autonomic hyperactivity, especially conjunctival tearing/injection; commonly misdiagnosed as trigeminal neuralgia</td></tr><tr><td>Treatment</td><td><strong>Absolute response to indomethacin</strong> (diagnostic and therapeutic)</td><td>Prevention: topiramate, valproate, gabapentin, lamotrigine (attacks too short to treat acutely)</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Chronic Daily Headache (CDH)</div><table style=\"margin:0\"><tr><th>Point</th></tr><tr><td>Not in ICHD-II R1; prevalence 3&ndash;5%</td></tr><tr><td>Defined as headache on <strong>&gt;15 days/month for &gt;3 months</strong></td></tr><tr><td>Four categories: <strong>transformed migraine</strong> (largest group, 70&ndash;80%), chronic tension-type headache, new daily persistent headache (NDPH), hemicrania continua</td></tr><tr><td>Transformed migraine: periodic migraine &ldquo;transforming&rdquo; to more frequent/continuous headache over years; treated as regular migraine</td></tr><tr><td>Hemicrania continua: rare, unremitting, unilateral; autonomic features (rhinorrhoea, conjunctival injection); responds to indomethacin</td></tr></table><p style=\"margin:14px 0 6px;font-size:13.5px;font-weight:700;color:var(--ink)\">Medication-overuse headache</p><table style=\"margin:0\"><tr><th>Provoking agents</th><td>Ergotamine, triptans, simple analgesics, opioids, combination analgesics</td></tr><tr><th>Prevalence</th><td>Present in up to 40% of chronic migraineurs</td></tr><tr><th>Management</th><td>Education, explanation and follow-up; <strong>abrupt withdrawal</strong> of simple analgesics and triptans, but <strong>gradual tapering</strong> of opioids</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Chronic Facial Pain</div><p style=\"margin:0 0 6px;font-size:13.5px;font-weight:700;color:var(--ink)\">Temporomandibular disorder (TMD)</p><table style=\"margin:0\"><tr><th>Definition</th><td>Generic term for muscle/joint conditions causing symptoms in the TMJ area; prevalence 30&ndash;46% (pain in 5&ndash;15%)</td></tr><tr><th>Investigations</th><td>Joint MRI, bone scintigraphy</td></tr><tr><th>Management</th><td>Self-care programme (jaw relaxation, softer diet, chewing technique, NSAIDs; avoid teeth grinding, prolonged opening, prone sleeping and caffeine), intra-oral splinting, analgesia, physiotherapy, TCAs for chronic pain, CBT techniques</td></tr></table><p style=\"margin:14px 0 6px;font-size:13.5px;font-weight:700;color:var(--ink)\">Trigeminal neuralgia</p><table style=\"margin:0\"><tr><th>Epidemiology</th><td>Incidence 3&ndash;5/100,000; peak onset in the 5th&ndash;6th decade</td></tr><tr><th>Aetiology</th><td>~80% associated with vascular compression; diagnosed in up to 5% of MS patients</td></tr><tr><th>Drug treatment</th><td>First-line <strong>carbamazepine (NNT 1.8)</strong>; others: baclofen, gabapentin, lamotrigine, oxcarbazepine, topiramate; ~70% initially controlled non-surgically</td></tr><tr><th>MVD</th><td>90% short-term relief, 55&ndash;70% long-term; annual recurrence 3.5%; mortality ~0.5%; hearing loss 1%</td></tr></table><p style=\"margin:14px 0 6px;font-size:13.5px;font-weight:700;color:var(--ink)\">Post-herpetic neuralgia (PHN)</p><table style=\"margin:0\"><tr><th>Epidemiology</th><td>Acute zoster incidence 400/100,000/year; PHN occurs in 15% of acute zoster cases</td></tr><tr><th>Definition</th><td>Pain persisting in the affected dermatome at 3 months</td></tr><tr><th>Features</th><td>Typically affects the V1 division; trophic changes (scarring, depigmentation, hair loss), allodynia; most resolve within the first year</td></tr><tr><th>Treatment</th><td><strong>Amitriptyline</strong> is the agent of choice (early treatment shortens duration/severity); gabapentin useful if insomnia; capsaicin cream, topical lidocaine and opioids also used</td></tr></table><p style=\"margin:14px 0 6px;font-size:13.5px;font-weight:700;color:var(--ink)\">Persistent idiopathic facial pain (formerly atypical facial pain)</p><table style=\"margin:0\"><tr><th>Epidemiology</th><td>Incidence 1/100,000; equal sex incidence, but more women seek care</td></tr><tr><th>Associations</th><td>Strong association with functional disorders (IBS) and psychological distress</td></tr><tr><th>Features</th><td>Continuous dull ache with intermittent severe episodes, poorly localised, sparing the joints/muscles of mastication; no sensory loss or physical signs; investigations normal</td></tr><tr><th>Treatment</th><td>Primary analgesics ineffective; poor response to diagnostic nerve block; TCA analgesic response is independent of the antidepressant effect; long-term support often needed</td></tr></table></div></div>\n</div>","relevantReading":[{"label":"Headache and chronic facial pain","source":"BJA Education","url":"https://www.bjaed.org/article/S1743-1816(17)30474-2/fulltext"},{"label":"Migraine: symptoms, types, pathophysiology and diagnosis","source":"BJA Education","url":"https://www.bjaed.org/article/S2058-5349(25)00072-1/fulltext"},{"label":"Migraine part 2: evidence-based acute and preventive treatment","source":"BJA Education","url":"https://www.bjaed.org/article/S2058-5349(25)00104-0/fulltext"}]}'::jsonb, 'published')
  on conflict (id) do nothing;
insert into questions (id, type, data, status) values ('q_emq_brachial_plexus_nerves_001', 'EMQ', '{"dateAdded":"2026-10-16","rotationIndex":159,"stem":"Nerves of the brachial plexus","lead":"For each description below, choose the single most likely nerve from the list above. Each option may be used once, more than once, or not at all.","options":["Axillary nerve","Median nerve","Medial cutaneous nerve of the arm","Medial cutaneous nerve of the forearm","Musculocutaneous nerve","Radial nerve","Suprascapular nerve","Ulnar nerve"],"questions":[{"question":"Arises from the upper trunk and passes through the suprascapular notch.","correct":6,"explanation":"<strong>G. Suprascapular nerve.</strong> It arises from the upper trunk (C5&ndash;6), crosses the suprascapular notch and supplies supraspinatus and infraspinatus; it has no cutaneous branch."},{"question":"Pierces coracobrachialis and supplies biceps brachii.","correct":4,"explanation":"<strong>E. Musculocutaneous nerve.</strong> A branch of the lateral cord (C5&ndash;7) that supplies coracobrachialis, biceps and brachialis, then continues as the lateral cutaneous nerve of the forearm."},{"question":"A terminal branch of the posterior cord that winds around the spiral groove of the humerus.","correct":5,"explanation":"<strong>F. Radial nerve.</strong> The largest branch of the posterior cord (C5&ndash;T1); it runs in the spiral groove, which is why mid-shaft humeral fractures can cause wrist drop."},{"question":"A terminal branch of the medial cord that passes behind the medial epicondyle.","correct":7,"explanation":"<strong>H. Ulnar nerve.</strong> It arises from the medial cord (C8&ndash;T1) and passes behind the medial epicondyle, where it is vulnerable to compression."},{"question":"Arises from the medial cord and supplies the skin over the medial aspect of the arm.","correct":2,"explanation":"<strong>C. Medial cutaneous nerve of the arm.</strong> It arises from the medial cord (T1) and supplies skin of the medial arm, communicating with the intercostobrachial nerve. The medial cutaneous nerve of the forearm supplies the forearm instead."}],"reference":"<div style=\"border:1px solid var(--border-strong);border-radius:14px;overflow:hidden\">\n  <div style=\"display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 18px;background:var(--coral)\">\n    <span style=\"font-weight:700;color:#fff;font-size:14.5px\">Brachial Plexus</span>\n    <div style=\"display:inline-flex;align-items:center;gap:7px;flex-shrink:0\">\n      <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"16\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"8\" x2=\"12.01\" y2=\"8\"/></svg>\n      <span style=\"font-family:var(--mono);font-size:10.5px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#fff;border:1px solid rgba(255,255,255,.55);border-radius:999px;padding:3px 9px\">Knowledge</span>\n    </div>\n  </div>\n  <div style=\"background:var(--surface-warm)\"><div style=\"padding:16px 18px 14px;\"><p style=\"margin:0;font-size:14px;line-height:1.65;color:var(--ink-soft)\">The brachial plexus is formed by the anterior rami of C5&ndash;T1 and is organised as roots, trunks, divisions, cords and branches. The cords are named by their relationship to the axillary artery, and the terminal nerves can be predicted from the cord of origin.</p></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Organisation</div><div style=\"text-align:center\"><img src=\"images/brachial-plexus-schematic.svg\" alt=\"Schematic of the brachial plexus showing roots C5 to T1, upper, middle and lower trunks, anterior and posterior divisions, lateral, posterior and medial cords and the main peripheral branches\" style=\"max-width:100%;border-radius:10px;margin-top:4px;border:1px solid #EDE3D7\"></div></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Origin of the Main Nerves</div><table style=\"margin:0\"><tr><th>Nerve</th><th>Origin</th><th>Root value</th></tr><tr><td>Suprascapular</td><td>Upper trunk</td><td>C5&ndash;6</td></tr><tr><td>Musculocutaneous</td><td>Lateral cord</td><td>C5&ndash;7</td></tr><tr><td>Axillary</td><td>Posterior cord</td><td>C5&ndash;6</td></tr><tr><td>Radial</td><td>Posterior cord</td><td>C5&ndash;T1</td></tr><tr><td>Median</td><td>Lateral and medial cords</td><td>C5&ndash;T1</td></tr><tr><td>Ulnar</td><td>Medial cord</td><td>C8&ndash;T1 (often C7)</td></tr><tr><td>Medial cutaneous nerves of arm and forearm</td><td>Medial cord</td><td>C8&ndash;T1</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Nerves Commonly Tested</div><table style=\"margin:0\"><tr><th>Nerve</th><th>Course and distribution</th></tr><tr><td>Suprascapular</td><td>Passes through the suprascapular notch; supplies supraspinatus and infraspinatus and sensation to the shoulder joint; no cutaneous branch</td></tr><tr><td>Musculocutaneous</td><td>Pierces coracobrachialis; supplies coracobrachialis, biceps and brachialis; continues as the lateral cutaneous nerve of the forearm</td></tr><tr><td>Radial</td><td>Winds around the spiral groove of the humerus; supplies triceps and the extensor muscles; skin of the posterior arm and forearm and the dorsum of the lateral hand</td></tr><tr><td>Ulnar</td><td>Passes behind the medial epicondyle; supplies flexor carpi ulnaris, the medial half of flexor digitorum profundus, the hypothenar muscles and most intrinsic hand muscles; medial one and a half fingers</td></tr><tr><td>Medial cutaneous nerve of arm</td><td>Arises from the medial cord (T1); skin of the medial arm; communicates with the intercostobrachial nerve</td></tr></table></div><div style=\"padding:16px 18px 14px;border-top:2px solid var(--border-strong);\"><div style=\"font-family:var(--mono);font-size:10.5px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:var(--coral-deep);margin-bottom:8px\">Relevance to Regional Anaesthesia and Pain</div><table style=\"margin:0\"><tr><th>Point</th></tr><tr><td>Interscalene block targets the roots/trunks (C5&ndash;7) and may spare the lower trunk, so the ulnar distribution (C8&ndash;T1) can be missed</td></tr><tr><td>Supraclavicular block targets trunks/divisions, infraclavicular block the cords, and axillary block the terminal branches</td></tr><tr><td>Lower trunk injury (C8&ndash;T1), for example from Pancoast tumour or thoracic outlet compression, affects ulnar-distribution sensation and intrinsic hand muscles</td></tr></table></div></div>\n</div>"}'::jsonb, 'published')
  on conflict (id) do nothing;
